            for (int e = 0; e < 8; ++e) {
                if (h == 0) ol[e] = X[e] * cc[e] - X[8+e] * ss[e];
                else        oh[e] = X[8+e] * cc[e] + X[e] * ss[e];
            }
        }
        ST8EL(YX, ol, pol); ST8EL(YX + 64, oh, pol);
    };
    #pragma unroll
    for (int d = 0; d < D - 1; ++d) if (t0 + d < t1) issue(x[d], st[d], y[d]);
    for (int t = t0; t < t1; t += D) {
        #pragma unroll
        for (int d = 0; d < D; ++d) {
            if (t + d >= t1) break;
            if (t + d + D - 1 < t1) issue(x[(d + D - 1) % D], st[(d + D - 1) % D], y[(d + D - 1) % D]);
            process(x[d], st[d], y[d]);
