            const float* cp = cs + (size_t)s_ * 128 + j * 8;
            const float* sp = sn + (size_t)s_ * 128 + j * 8;
            LD8(cp, c); LD8(cp + 64, (c + 8)); LD8(sp, sv); LD8(sp + 64, (sv + 8));
#pragma unroll
            for (int i = 0; i < 4; ++i) {
                tab[i][tid]     = make_float4(c[4*i], c[4*i+1], c[4*i+2], c[4*i+3]);
                tab[4 + i][tid] = make_float4(sv[4*i], sv[4*i+1], sv[4*i+2], sv[4*i+3]);
            }
        }
        float ol[8], oh[8];
#pragma unroll
        for (int h = 0; h < 2; ++h) {
            const float4 c0 = tab[2*h][tid], c1 = tab[2*h+1][tid], s0 = tab[4+2*h][tid], s1 = tab[5+2*h][tid];
            const float cc[8] = {c0.x, c0.y, c0.z, c0.w, c1.x, c1.y, c1.z, c1.w};
            const float ss[8] = {s0.x, s0.y, s0.z, s0.w, s1.x, s1.y, s1.z, s1.w};
#pragma unroll
            for (int e = 0; e < 8; ++e) {
                if (h == 0) ol[e] = X[e] * cc[e] - X[8+e] * ss[e];
                else        oh[e] = X[8+e] * cc[e] + X[e] * ss[e];
            }
        }
        ST8EL(YX, ol, pol);
        ST8EL(YX + 64, oh, pol);
    };
#pragma unroll
    for (int d = 0; d < D - 1; ++d) if (t0 + d < t1) issue(x[d], st[d], y[d]);
    for (int t = t0; t < t1; t += D) {
#pragma unroll
        for (int d = 0; d < D; ++d) {
            if (t + d >= t1) break;
            if (t + d + D - 1 < t1) issue(x[(d + D - 1) % D], st[(d + D - 1) % D], y[(d + D - 1) % D]);
            process(x[d], st[d], y[d]);
        }
    }
}

